  const codTag = String(tags.plano_escolhido || '').toUpperCase().match(/[VE]-[A-Z0-9]+-[A-Z]+/);
  const cod = (codTag && codTag[0]) || (ctx.conversa || {}).plano_escolhido;
  let ch = pls.find((p) => p.codigo === cod) || null;
