// NIOGEN | n8n/mari/n11_saida.js — nó "11 · Saída" do mari_principal (04/11/2026)
// Ponto único de saída de todos os caminhos. Monta o corpo devolvido pela rota de teste
// (modo 'teste') ou a mensagem a enviar pelo Chatwoot (modo 'chatwoot').
const ex = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const j = $input.first().json || {};
const e = ex('2 · Entrada') ? ($('2 · Entrada').first().json || {}) : {};

let saida;
if (j.saida) {
  saida = j.saida;
} else if (ex('2r · Supabase registrar calado')) {
  saida = { ...(($('2h · Guard humano').first().json || {}).saida || { silencio: true }), registrado: j.ignorado === false };
} else if (ex('10b · Supabase salvar turno')) {
  const s = $('10 · Salvar turno').first().json;
  const r = s.r || {};
  const h = ex('9 · Handoff') ? $('9 · Handoff').first().json : null;
  saida = {
    resposta: r.texto,
    conversa_id: r.conversaId,
    etapa: r.handoff ? 'handoff' : (r.upd && r.upd.etapa) || null,
    handoff: r.handoff ? { motivo: r.handoff.motivo, ...(h || {}) } : null,
    tags: r.tags || {},
    upd: r.upd || {},
    modelo: r.modelo,
    tokens_in: r.tokensIn, tokens_out: r.tokensOut, latencia_ms: r.latenciaMs,
    // @ensaio-inicio
    uso: r.uso || null,   // 07/11: usage separado + corte de histórico medido (só no ensaio, rota de teste)
    // @ensaio-fim
    corrigido: r.violacoesCorrigidas || null,
    erro: r.erro ? r.erro.mensagem : null,
    prompt: r.promptVersao || null,
    // Balões (v3, "||"): o envio pelo Chatwoot manda um por vez, com o atraso antes de cada um
    // (≈ 1 s a cada 60 caracteres, mínimo 2 s, máximo 6 s — proposta de tom §5).
    // Teste real 07/11 23h09 (conversa #1): com interativo, a pergunta inteira vira o corpo dos botões e não sobra balão.
    // O fallback para r.texto mandava o histórico ("…\n\n[botões: Sim / Não]") como texto público pelo Chatwoot —
    // o cliente via a marca e a pergunta duas vezes. Com interativo, balões vazios = só a mensagem interativa.
    baloes: (Array.isArray(r.baloes) && r.baloes.length ? r.baloes : (r.interativo ? [] : (r.texto ? [r.texto] : []))),
    emoji_ajustes: r.emojiAjustes || null,
    interativo: r.interativo || null,   // v7: carrossel/botões (enviado pela Graph API depois dos balões)
  };
  saida.atrasos = saida.baloes.map((b) => Math.min(6, Math.max(2, Math.round(b.length / 60))));
  // 07/11 (conversa #1, "Sim" que chegou 0,3 s depois da checagem): o "digitando" do 1º balão agora acontece ANTES da
  // checagem de mensagem nova (7w · Espera 1º balão → 7b → 7c). Aqui ele vira quase zero para não esperar duas vezes.
  if (ex('7w · Espera 1º balão') && saida.atrasos.length) saida.atrasos[0] = 0.3;
} else if (ex('7f · Supabase abortar')) {
  saida = { abortado: true, motivo: 'mensagem nova chegou durante a resposta — a execução mais nova responde' };
} else if (j.esgotado) {
  saida = { erro: 'conversa ocupada por mais de 45 s (lock)' };
} else if (j.silencio === true && j.conversa_id) {
  saida = { silencio: true, status: j.status, conversa_id: j.conversa_id, motivo: 'conversa em handoff — o humano conduz' };
} else if (j.resultado) {
  saida = { resultado: j.resultado, status: j.status || null };
} else {
  saida = { erro: 'saída não identificada' };
}

// Quem decide o caminho de saída é o GATILHO, não o modo: execução da rota de teste sempre responde
// pelo 12t (inclusive os comandos admin com o modo em 'chatwoot'); execução do Chatwoot envia pelo 12c.
return [{ json: {
  modo: ex('1 · Webhook Mari teste') ? 'teste' : 'chatwoot',
  saida,
  // Modo chatwoot com interativo e sem balão: resposta vazia → o 11c pula os balões e vai direto ao 12x (botões).
  // A rota de teste continua devolvendo saida.resposta inteira (o 12t responde com saida).
  resposta: (saida.interativo && Array.isArray(saida.baloes) && !saida.baloes.length) ? '' : (saida.resposta || ''),
  baloes: saida.baloes || (saida.resposta ? [saida.resposta] : []),
  atrasos: saida.atrasos || (saida.resposta ? [2] : []),
  chatwootConversationId: e.chatwootConversationId || null,
  config: e.config || {},
  // v7: quem recebe a mensagem interativa — WhatsApp real (modo chatwoot) ou o celular liberado no ensaio ("tel real").
  interativo: saida.interativo || null,
  telefone: e.telefone || null,
  enviarInterativo: !!saida.interativo && (e.modo === 'chatwoot' || e.enviarReal === true),
} }];

// NIOGEN | n8n/mari/n12a_baloes.js — nó "12a · Balões" do mari_principal (04/11/2026, prompt v3)
// Um item por balão (a Mari separa com "||"; o 7 · Extrair corta em até 3). O laço 12b → 12w → 12c manda um
// por vez, com o atraso antes de cada um (≈ 1 s a cada 60 caracteres, mínimo 2 s, máximo 6 s — proposta de tom §5).
// Resposta sem "||" (v2, mídia, despedida de segurança) = um balão só, como antes.
const j = $input.first().json;
// 07/11 23h09 (conversa #1): com interativo, nunca cair no texto do histórico (ele traz "[botões: …]").
const comInterativo = !!(j.saida && j.saida.interativo);
const baloes = Array.isArray(j.baloes) && j.baloes.length ? j.baloes : (!comInterativo && j.resposta ? [j.resposta] : []);
const atrasos = Array.isArray(j.atrasos) ? j.atrasos : [];
return baloes.map((conteudo, i) => ({ json: {
  conteudo,
  // 0,3 s no 1º balão = o "digitando" já aconteceu antes da checagem de mensagem nova (7w).
  atraso: atrasos[i] != null ? atrasos[i] : Math.min(6, Math.max(2, Math.round(conteudo.length / 60))),
  ordem: i + 1,
  total: baloes.length,
  chatwootConversationId: j.chatwootConversationId,
  config: j.config,
} }));

// NIOGEN | n8n/mari/n12y_interativo.js — nó "12y · Montar interativo" do mari_principal (06/11/2026, prompts 26 + 27, Mari v7)
// Monta a mensagem interativa (carrossel de ofertas ou botões) para a Graph API do WhatsApp — SEMPRE pela Graph API
// (phone_number_id 1342993658907403, credencial n8n "WABA Nio (Nio_API)"), nunca pelo Chatwoot. Só dentro da janela de
// 24 h (é resposta ao cliente): mensagem interativa, não template. Textos e imagens vêm do 7 · Extrair (0047, exatos da spec).
// Depois do envio, o 12v deixa uma NOTA PRIVADA no Chatwoot (o backoffice vê o que a Mari mandou) — o 2 · Entrada ignora nota privada.
const s = $('11 · Saída').first().json;
const it = s.interativo || {};
const to = String(s.telefone || '').replace(/\D/g, '');

let interactive;
if (it.tipo === 'carrossel') {
  interactive = {
    type: 'carousel',
    body: { text: it.corpo },
    action: {
      cards: (it.cartoes || []).map((k, i) => ({
        card_index: i,
        type: 'button',
        header: { type: 'image', image: { link: k.imagem } },
        body: { text: k.texto },
        action: { buttons: k.botoes.map((b) => ({ type: 'quick_reply', quick_reply: { id: b.id, title: b.title } })) },
      })),
    },
  };
} else {
  interactive = {
    type: 'button',
    body: { text: it.corpo },
    action: { buttons: (it.botoes || []).map((b) => ({ type: 'reply', reply: { id: b.id, title: b.title } })) },
  };
}

const nota = it.tipo === 'carrossel'
  ? `🤖 Mari enviou ${it.resumo}`
  : `🤖 Mari enviou ${it.resumo}\n\n${it.corpo}`;

return [{ json: {
  graph: { messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'interactive', interactive },
  nota,
  fallbackTexto: it.fallbackTexto || '',
  tipo: it.tipo,
  conversaId: (s.saida || {}).conversa_id || null,
  chatwootConversationId: s.chatwootConversationId,
  config: s.config,
} }];

// NIOGEN | n8n/mari/n12v_interativo_resultado.js — nó "12v · Resultado interativo" do mari_principal (06/11/2026, Mari v7)
// Enviou (a Graph API devolveu o id da mensagem) → NOTA PRIVADA no Chatwoot com o que a Mari mandou ("🤖 Mari enviou …").
// Falhou (erro da Meta, imagem fora do ar…) → manda a LISTA/PERGUNTA EM TEXTO pelo Chatwoot (público) e registra em mari_erros
// (spec §1: "Carrossel falhou → lista em texto do Passo 3 + mari_erros"). Nada de token ou dado de cliente no log.
const m = $('12y · Montar interativo').first().json;
const r = $input.first().json || {};
const id = r.messages && r.messages[0] && r.messages[0].id;
const ok = !!id;
const erroMeta = ok ? null : String((r.error && (r.error.message || r.error.error_user_msg)) || r.message || JSON.stringify(r).slice(0, 300));

return [{ json: {
  ok,
  conteudo: ok ? m.nota : (m.fallbackTexto || ''),
  privada: ok,
  chatwootConversationId: m.chatwootConversationId,
  config: m.config,
  erroPayload: ok ? null : {
    conversa_id: m.conversaId, no_n8n: '12z · WABA enviar',
    mensagem: `interativo (${m.tipo}) não enviado: ${erroMeta}`,
    payload: { tipo: m.tipo, codigo: r.error && r.error.code, subcodigo: r.error && r.error.error_subcode },
  },
} }];

// NIOGEN | n8n/mari/nE1_log_erro.js — nó "E1 · Log erro" do mari_principal (04/11/2026)
// Error Trigger do próprio workflow → mari_erros (espelho do "Log Erro" da Renata).
// O lock da conversa expira sozinho (TTL 45 s).
const e = $input.first().json || {};
const exec = e.execution || {};
return [{ json: { erroPayload: {
  no_n8n: exec.lastNodeExecuted || 'desconhecido',
  mensagem: String(exec.error?.message || 'erro sem mensagem').slice(0, 2000),
  payload: { execution_id: exec.id || null, workflow: e.workflow?.name || null, modo: exec.mode || null },
} } }];
